namespace MUnique.OpenMU.GameLogic.PlugIns.EventRework;

using MUnique.OpenMU.DataModel.Configuration.Items;

/// <summary>
/// A drop generator of an event in which each killed monster drops one jewel, chosen by weight, and nothing else.
/// The rewards are generated by the drop generator of the game.
/// </summary>
public sealed class EventJewelDropGenerator : IDropGenerator
{
    private readonly IDropGenerator _gameDropGenerator;
    private readonly IReadOnlyList<(ItemDefinition Definition, int Weight)> _jewels;
    private readonly int _totalWeight;

    /// <summary>
    /// Initializes a new instance of the <see cref="EventJewelDropGenerator"/> class.
    /// </summary>
    /// <param name="gameDropGenerator">The drop generator of the game.</param>
    /// <param name="jewels">The jewels with their weights.</param>
    public EventJewelDropGenerator(IDropGenerator gameDropGenerator, IReadOnlyList<(ItemDefinition Definition, int Weight)> jewels)
    {
        this._gameDropGenerator = gameDropGenerator;
        this._jewels = jewels;
        this._totalWeight = jewels.Sum(j => j.Weight);
    }

    /// <inheritdoc />
    public ValueTask<(IEnumerable<Item> Items, uint? Money)> GenerateItemDropsAsync(MonsterDefinition monster, int gainedExperience, Player player)
    {
        if (this._totalWeight <= 0)
        {
            return ValueTask.FromResult<(IEnumerable<Item>, uint?)>((Enumerable.Empty<Item>(), null));
        }

        var threshold = Rand.NextInt(0, this._totalWeight);
        var definition = this._jewels[^1].Definition;
        foreach (var (jewel, weight) in this._jewels)
        {
            if (threshold < weight)
            {
                definition = jewel;
                break;
            }

            threshold -= weight;
        }

        var item = new TemporaryItem
        {
            Definition = definition,
            Durability = 1,
        };

        return ValueTask.FromResult<(IEnumerable<Item>, uint?)>((item.GetAsEnumerable(), null));
    }

    /// <inheritdoc />
    public Item? GenerateItemDrop(DropItemGroup group) => this._gameDropGenerator.GenerateItemDrop(group);

    /// <inheritdoc />
    public (Item? Item, uint? Money, ItemDropEffect DropEffect) GenerateItemDrop(IEnumerable<DropItemGroup> groups) => this._gameDropGenerator.GenerateItemDrop(groups);
}
